def priority(item, bins):
    # We prioritize bins that have the most remaining space after adding the item
    # This is equivalent to maximizing (bin_capacity - item), so we minimize -(bin_capacity - item)
    return -(bins - item)

def priority(item, bins):
    remaining = bins - item
    return -np.abs(remaining)

def priority(item, bins):
    remaining = bins - item
    return -np.where(remaining > 0, remaining, np.inf)
